components.css:
.brick-onboarding{display:grid;gap:14px;padding:18px;border:1px solid #dbe3ef;border-radius:8px;background:#fff;color:#172033}
    .brick-onboarding *{box-sizing:border-box}
    .brick-onboarding>span{color:#2563eb;font-size:12px;font-weight:900}
    .brick-onboarding>strong{font-size:22px;letter-spacing:0}
    .brick-onboarding .onboarding-progress-steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:0;padding:0;list-style:none}
    .brick-onboarding .onboarding-progress-steps li{position:relative;display:grid;grid-template-columns:auto 1fr;gap:6px 9px;align-items:center;min-height:78px;padding:12px;border:1px solid #dbe3ef;border-radius:8px;background:#f8fbff}
    .brick-onboarding .onboarding-progress-steps li::after{content:"";position:absolute;top:24px;right:-13px;width:13px;height:2px;background:#bfdbfe}
    .brick-onboarding .onboarding-progress-steps li:last-child::after{display:none}
    .brick-onboarding .onboarding-progress-steps b{width:28px;height:28px;display:grid;place-items:center;border-radius:8px;background:#dbeafe;color:#1d4ed8;font-size:12px}
    .brick-onboarding .onboarding-progress-steps span{color:#172033;font-size:13px;font-weight:900}
    .brick-onboarding .onboarding-progress-steps small{grid-column:2;color:#64748b;font-size:11px;font-weight:800}
    .brick-onboarding .onboarding-progress-steps .done{border-color:#bbf7d0;background:#f0fdf4}
    .brick-onboarding .onboarding-progress-steps .done b{background:#16a34a;color:#fff}
    .brick-onboarding .onboarding-progress-steps .active{border-color:#93c5fd;background:#eff6ff;box-shadow:0 0 0 2px rgba(37,99,235,.08)}
    .brick-onboarding .onboarding-progress-steps .active b{background:#2563eb;color:#fff}
    @media(max-width:720px){.brick-onboarding .onboarding-progress-steps{grid-template-columns:1fr}.brick-onboarding .onboarding-progress-steps li::after{left:25px;right:auto;top:auto;bottom:-13px;width:2px;height:13px}}
